from typing import Any, Dict, List, Union


class OCRRequest:
    def __init__(self, image_path: str, language: str = 'en'):
        self.image_path = image_path
        self.language = language


class OCRResponse:
    def __init__(self, text: str, confidence: float):
        self.text = text
        self.confidence = confidence


class LayoutRequest:
    def __init__(self, image_path: str):
        self.image_path = image_path


class LayoutResponse:
    def __init__(self, elements: List[Dict[str, Any]]):
        self.elements = elements


def normalize_text(text: str) -> str:
    return text.strip().lower()


def normalize_layout(elements: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized_elements = []
    for element in elements:
        normalized_element = {k.lower(): v for k, v in element.items()}
        normalized_elements.append(normalized_element)
    return normalized_elements

import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

# Configuration for Amazon Textract
AWS_REGION = 'us-west-2'

def configure_textract_client():
    try:
        session = boto3.Session()
        textract_client = session.client('textract', region_name=AWS_REGION)
        return textract_client
    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f'AWS credentials error: {e}')
        return None

# Helper utility for OCR
def extract_text_from_document(document_path):
    textract_client = configure_textract_client()
    if textract_client is None:
        return None
    try:
        with open(document_path, 'rb') as document:
            response = textract_client.detect_document_text(Document={'Bytes': document.read()})
            return response
    except Exception as e:
        print(f'Error extracting text: {e}')
        return None

# Helper utility for Layout Extraction
def extract_layout_from_document(document_path):
    textract_client = configure_textract_client()
    if textract_client is None:
        return None
    try:
        with open(document_path, 'rb') as document:
            response = textract_client.analyze_document(Document={'Bytes': document.read()}, FeatureTypes=['TABLES', 'FORMS'])
            return response
    except Exception as e:
        print(f'Error extracting layout: {e}')
        return None

import boto3

def extract_key_values(document_path):
    textract_client = boto3.client('textract')
    with open(document_path, 'rb') as document:
        response = textract_client.analyze_document(
            Document={'Bytes': document.read()},
            FeatureTypes=['FORMS'])
    key_values = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = None
            value = None
            for child_id in block['ChildIds']:
                child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                if child_block['BlockType'] == 'WORD':
                    if key is None:
                        key = child_block['Text']
                    else:
                        value = child_block['Text']
            if key and value:
                key_values[key] = value
    return key_values

import boto3

def extract_tables(document_path):
    textract = boto3.client('textract')
    with open(document_path, 'rb') as document:
        imageBytes = document.read()
    response = textract.analyze_document(
        Document={'Bytes': imageBytes},
        FeatureTypes=['TABLES'])
    tables = []
    for block in response['Blocks']:
        if block['BlockType'] == 'TABLE':
            table = {
                'Id': block['Id'],
                'Rows': []
            }
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        for block in response['Blocks']:
                            if block['Id'] == child_id:
                                if block['BlockType'] == 'CELL':
                                    cell = {
                                        'ColumnIndex': block.get('ColumnIndex', None),
                                        'RowIndex': block.get('RowIndex', None),
                                        'Text': block.get('Text', '')
                                    }
                                    table['Rows'].append(cell)
            tables.append(table)
    return tables

if __name__ == '__main__':
    document_path = 'path/to/your/document.pdf'
    tables = extract_tables(document_path)
    for table in tables:
        print(table)

import boto3

def extract_layout(document_path):
    textract_client = boto3.client('textract')

    with open(document_path, 'rb') as document:
        image_bytes = document.read()

    response = textract_client.analyze_document(
        Document={'Bytes': image_bytes},
        FeatureTypes=['TABLES', 'FORMS']
    )

    blocks = response['Blocks']

    for block in blocks:
        if block['BlockType'] == 'LINE':
            print('LINE: ' + block['Text'])
        elif block['BlockType'] == 'TABLE':
            print('TABLE: ' + block['Text'])

if __name__ == '__main__':
    document_path = 'sample_document.jpg'
    extract_layout(document_path)
